const site: Provenance = {
  sourceUrl: PE001_OFFICIAL_SITE,
  sourceCheckedDate: PE001_LAST_RESEARCHED,
  verificationStatus: "verified",
};
const bookings: Provenance = { ...site, sourceUrl: PE001_BOOKINGS };
const parties: Provenance = { ...site, sourceUrl: PE001_PARTIES };

/** A 2-hour play pass: every attraction, one adult included, plus HST. */
function pass(
  id: string,
  label: string,
  day: "weekday" | "weekend_holiday",
  ageMin: number,
  ageMax: number | null,
  amount: number,
): VenuePrice {
  return {
    ...bookings,
    id,
    kind: "admission",
    label,
    audience: "child",
    ageMin,
    ageMax,
    durationMinutes: 120,
    includesNote: "every attraction and 1 adult",
    amount,
    isFree: false,
    currency: "CAD",
    requiredAddon: false,
    plusTax: true,
    dayType: day,
    adultsIncluded: 1,
  };
}

function party(
  id: string,
  kids: number,
  day: "weekday" | "weekend_holiday",
  amount: number,
  notes: string,
  source: Provenance = parties,
): VenuePrice {
  return {
    ...source,
    id,
    kind: "party",
    label: `${kids} kids + ${kids} adults`,
    audience: "group",
    durationMinutes: 120,
    amount,
    isFree: false,
    currency: "CAD",
    requiredAddon: false,
    plusTax: true,
    dayType: day,
    notes,
  };
}

